INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob alle Netzwerke die gleiche Anzahl an Hosts haben?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von der Klasse"}, {"text": "Ja", "correct": false, "because": "Klassen variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adressbereich gehört zu einem großen Netzwerk mit vielen Hosts?', 3, '[{"text": "Klasse A", "correct": true, "because": "Bis zu 16 Mio. Hosts"}, {"text": "Klasse C", "correct": false, "because": "Nur 254 Hosts"}, {"text": "Klasse D", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine typische Netzwerkadresse?', 5, '[{"text": "Erstes Oktett definiert Klasse", "correct": true, "because": "Bestimmt Bereich"}, {"text": "Netzwerk- und Host-Teil", "correct": true, "because": "Trennt Adressen"}, {"text": "Subnetzmaske", "correct": true, "because": "Definiert Teilnetze"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse B hat 65.534 Hosts. b) Klasse E ist für öffentliche Netze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse E ist experimentell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk einrichte?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Trennt Netzwerk"}, {"text": "Adressbereich", "correct": false, "because": "Definiert Klasse"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Klasse C für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur 254 Hosts"}, {"text": "Ja", "correct": false, "because": "Klasse A besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich beginnt mit 192?', 3, '[{"text": "Klasse C", "correct": true, "because": "192.0.0.0 bis 223.255.255.255"}, {"text": "Klasse A", "correct": false, "because": "0 bis 127"}, {"text": "Klasse B", "correct": false, "because": "128 bis 191"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat Klasse A?', 5, '[{"text": "8-Bit-Netzwerkteil", "correct": true, "because": "Große Hostanzahl"}, {"text": "Bis 16 Mio. Hosts", "correct": true, "because": "Breiter Bereich"}, {"text": "Subnetzmaske 255.0.0.0", "correct": true, "because": "Standard"}, {"text": "Multicast", "correct": false, "because": "Klasse D"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Klasse D für Multicast ist und b) Klasse C nur 10 Hosts hat. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse C hat 254 Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Netzwerkadresse zu bestimmen?', 4, '[{"text": "Erstes Oktett", "correct": false, "because": "Definiert Klasse"}, {"text": "Subnetzmaske", "correct": false, "because": "Trennt Netzwerk"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat Klasse B mehr Hosts als Klasse A?', 2, '[{"text": "Nein", "correct": true, "because": "A hat mehr"}, {"text": "Ja", "correct": false, "because": "A: 16 Mio., B: 65.534"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken helfen bei der Adressaufteilung?', 4, '[{"text": "Subnetting", "correct": true, "because": "Teilt Netzwerke"}, {"text": "CIDR", "correct": true, "because": "Flexiblere Masken"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Klasse E öffentlich genutzt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Reserviert für Forschung"}, {"text": "Ja", "correct": false, "because": "Nicht öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Adressklasse?', 3, '[{"text": "Netzwerkgröße definieren", "correct": true, "because": "Hosts bestimmen"}, {"text": "Design verbessern", "correct": false, "because": "Kein Faktor"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse A hat 255.0.0.0 Maske. b) Klasse C ist für kleine Netze.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Beide korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Subnetzmaske?', 4, '[{"text": "Trennt Netzwerk und Host", "correct": true, "because": "Definiert Bereiche"}, {"text": "Komprimiert Daten", "correct": false, "because": "Anderer Zweck"}, {"text": "Farbt Daten", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Klasse D für normale Netze ist?', 2, '[{"text": "Nein", "correct": true, "because": "Für Multicast"}, {"text": "Ja", "correct": false, "because": "Spezielle Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Adressklasse nützlich?', 5, '[{"text": "Hostanzahl", "correct": true, "because": "Bestimmt Größe"}, {"text": "Netzwerktrennung", "correct": true, "because": "Definiert Bereiche"}, {"text": "Einfache Verwaltung", "correct": true, "because": "Klar strukturiert"}, {"text": "Schnelle Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat Klasse B die Maske 255.255.0.0?', 3, '[{"text": "Ja", "correct": true, "because": "Standard für Klasse B"}, {"text": "Nein", "correct": false, "because": "Korrekte Maske"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Klasse C?', 4, '[{"text": "Kleines Büro mit 200 Geräten", "correct": true, "because": "Passt zu 254 Hosts"}, {"text": "Große Firma mit 1 Mio. Geräten", "correct": false, "because": "Klasse A"}, {"text": "Multicast-Streaming", "correct": false, "because": "Klasse D"}]');
